create or replace function public.prevent_locked_corpus_change() returns trigger language plpgsql as $$begin if exists(select 1 from corpora where id=coalesce(new.corpus_id,old.corpus_id) and locked_at is not null) then raise exception 'Corpus is locked';end if;return coalesce(new,old);end$$;create trigger immutable_corpus_items before insert or update or delete on corpus_items for each row execute function prevent_locked_corpus_change();
